(()=>{"use strict";const num=n=>Number(n).toLocaleString(typeof window<"u"&&window.CMI18n?window.CMI18n.formatLocale:"en-US",{maximumFractionDigits:2,minimumFractionDigits:2}),$=id=>document.getElementById(id);function render(){const a=parseFloat($("la").value)||0,b=parseFloat($("lb").value)||0;if(!(a>0)||!(b>0)){$("result").textContent="\u2014",$("chipAng").textContent="\u2014",$("chipArea").textContent="\u2014",$("chipPer").textContent="\u2014";const vd2=$("verdict");vd2.className="verdict warn",$("verdictText").textContent="Enter both legs above zero.";return}const c=Math.sqrt(a*a+b*b),angA=Math.atan2(a,b)*180/Math.PI,angB=90-angA;$("result").textContent=num(c),$("chipAng").textContent=num(angA)+"\xB0 / "+num(angB)+"\xB0",$("chipArea").textContent=num(.5*a*b),$("chipPer").textContent=num(a+b+c);const vd=$("verdict");vd.className="verdict",$("verdictText").textContent="Check: "+num(a)+"\xB2 + "+num(b)+"\xB2 = "+num(a*a+b*b)+" = "+num(c)+"\xB2."}document.querySelectorAll("input").forEach(e=>e.addEventListener("input",render)),render()})();
